import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"流水线阶段、门禁与故障定位","description":"事件触发、权限、依赖、缓存制品、状态及runner排错，历史GitLab草稿仅作对照。","frontmatter":{"title":"流水线阶段、门禁与故障定位","description":"事件触发、权限、依赖、缓存制品、状态及runner排错，历史GitLab草稿仅作对照。","showdocs":{"topics":[{"id":"cicd","title":"CI/CD","link":"/topics/cicd/"},{"id":"engineering","title":"编辑器与 IDE","link":"/topics/engineering/"},{"id":"docker","title":"Docker","link":"/topics/docker/"}],"kind":"CI/CD上手与对象","scope":"general","audience":"company","group":"工程与工具","seriesTitle":"CI/CD：静态流水线与门禁","summary":"事件触发、权限、依赖、缓存制品、状态及runner排错，历史GitLab草稿仅作对照。","status":"active","related":[{"title":"CI/CD：完整实践与解答","link":"/tools/collaboration-delivery/cicd/practice/application","kind":"CI/CD完整实践与解答","scope":"general","audience":"general"},{"title":"编辑器与IDE：完整实践与解答","link":"/tools/developer-tools/engineering/practice/application","kind":"编辑器与IDE完整实践与解答","scope":"general","audience":"general"},{"title":"Docker 操作与命令","link":"/systems/docker/plus/ecosystem/docker-general-general","kind":"命令","scope":"general","audience":"general"},{"title":"Docker 常用命令与对象速查","link":"/systems/docker/commands","kind":"命令","scope":"general","audience":"general"},{"title":"Docker 排障：构建、退出、网络与存储","link":"/systems/docker/troubleshooting","kind":"故障排查","scope":"general","audience":"general"}],"prev":false,"next":{"text":"CI/CD：完整实践与解答","link":"/tools/collaboration-delivery/cicd/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"CI/CD：完整实践与解答","link":"/tools/collaboration-delivery/cicd/practice/application"}},"headers":[],"relativePath":"tools/collaboration-delivery/cicd/pipelines-and-gates.md","filePath":"tools/collaboration-delivery/cicd/pipelines-and-gates.md"}'),s={name:"tools/collaboration-delivery/cicd/pipelines-and-gates.md"};function o(n,e,l,p,c,d){return r(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="流水线阶段、门禁与故障定位" tabindex="-1">流水线阶段、门禁与故障定位 <a class="header-anchor" href="#流水线阶段、门禁与故障定位" aria-label="Permalink to &quot;流水线阶段、门禁与故障定位&quot;">​</a></h1><h2 id="part-1" tabindex="-1">确定流水线阶段、事件与权限 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;确定流水线阶段、事件与权限 {#part-1}&quot;">​</a></h2><p>需能阅读 YAML 与 Python 文件路径。以<a href="/tools/collaboration-delivery/cicd/practice/application#source">语法门禁示例</a>区分事件、检出和检查：<code>check.py</code> 只对 <code>examples/</code> 做 AST 解析，不执行例子。本地阅读以 Python 3.11+ 为基准；远端 YAML 面向公开 GitHub 仓库与 Ubuntu runner，未启用。 示例未在本轮执行。</p><h3 id="part-1-stages" tabindex="-1">CI/CD 阶段 <a class="header-anchor" href="#part-1-stages" aria-label="Permalink to &quot;CI/CD 阶段 {#part-1-stages}&quot;">​</a></h3><p>CI/CD阶段区分检查、构建、制品和部署。持续集成首先让同一提交接受可重复检查，部署涉及环境与授权；本课程只交付静态工作流，不触发远端任务或发布。</p><h3 id="part-1-trigger" tabindex="-1">CI/CD 触发条件 <a class="header-anchor" href="#part-1-trigger" aria-label="Permalink to &quot;CI/CD 触发条件 {#part-1-trigger}&quot;">​</a></h3><p>CI/CD触发条件决定哪些提交进入检查。pull_request适合验证候选补丁，push保护主分支；路径过滤可能导致必须检查永远等待，需与分支保护要求一起设计。</p><h3 id="part-1-permissions" tabindex="-1">CI/CD 最小权限 <a class="header-anchor" href="#part-1-permissions" aria-label="Permalink to &quot;CI/CD 最小权限 {#part-1-permissions}&quot;">​</a></h3><p>CI/CD最小权限从只读contents开始。检查源码不需要写仓库或部署权限；不可信贡献代码与秘密凭据隔离，不能为了获得秘密而把任意PR代码放进高权限事件。</p><p><span id="part-3-sources"></span></p><p><span id="part-2-sources"></span></p><h3 id="part-1-sources" tabindex="-1">依据与适用范围 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;依据与适用范围 {#part-1-sources}&quot;">​</a></h3><ul><li><a href="https://docs.github.com/en/actions/reference/workflows-and-actions/workflow-syntax" target="_blank" rel="noopener noreferrer">本课官方依据</a>，资料核对日2026-10-17。</li></ul><p>以上依据用于解释本文列明的规则；示例未执行，不代表产品全部能力或跨平台验证。历史资料的版本、账号与界面位置需按目标环境确认。</p><h2 id="part-2" tabindex="-1">区分依赖、缓存、制品与门禁 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;区分依赖、缓存、制品与门禁 {#part-2}&quot;">​</a></h2><h3 id="part-2-dependency" tabindex="-1">CI/CD 依赖固定 <a class="header-anchor" href="#part-2-dependency" aria-label="Permalink to &quot;CI/CD 依赖固定 {#part-2-dependency}&quot;">​</a></h3><p>CI/CD依赖固定包括运行时和第三方Action。教材工作流不引用第三方Action，仅用runner内置Python作AST检查；runner镜像仍会变化，不能把静态YAML当作可复现执行环境的证明。</p><h3 id="part-2-cache" tabindex="-1">CI/CD 缓存与制品 <a class="header-anchor" href="#part-2-cache" aria-label="Permalink to &quot;CI/CD 缓存与制品 {#part-2-cache}&quot;">​</a></h3><p>CI/CD缓存是加速依赖恢复，制品是本次构建的可审阅输出。缓存命中不证明测试通过，制品应关联提交；不要把包含秘密的工作目录整体缓存或上传。</p><h3 id="part-2-gates" tabindex="-1">CI/CD 门禁状态 <a class="header-anchor" href="#part-2-gates" aria-label="Permalink to &quot;CI/CD 门禁状态 {#part-2-gates}&quot;">​</a></h3><p>CI/CD门禁状态要区分失败、跳过和未运行。允许失败的任务不能作为关键质量门禁；矩阵展开与条件判断应确保至少一条实际检查路径，状态名称变化还会影响保护规则。</p><h2 id="part-3" tabindex="-1">定位工作目录、泄露与平台差异 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;定位工作目录、泄露与平台差异 {#part-3}&quot;">​</a></h2><h3 id="part-3-paths" tabindex="-1">CI/CD 工作目录 <a class="header-anchor" href="#part-3-paths" aria-label="Permalink to &quot;CI/CD 工作目录 {#part-3-paths}&quot;">​</a></h3><p>CI/CD工作目录以仓库检出位置为基准，脚本相对路径依赖defaults.run.working-directory或具体步骤cwd。runner已有环境不能替代检出源码；本例明确先用原生git获取当前提交，读者自行授权后才可使用。</p><h3 id="part-3-secrets" tabindex="-1">CI/CD 日志泄露 <a class="header-anchor" href="#part-3-secrets" aria-label="Permalink to &quot;CI/CD 日志泄露 {#part-3-secrets}&quot;">​</a></h3><p>CI/CD日志泄露可能来自回显环境、调试命令或制品打包。平台遮罩不是完整防护，编码或拆分后的秘密仍可能出现；避免将令牌放入命令行和上传目录，若泄露需轮换而非只删日志。</p><h3 id="part-3-portability" tabindex="-1">CI/CD 平台差异 <a class="header-anchor" href="#part-3-portability" aria-label="Permalink to &quot;CI/CD 平台差异 {#part-3-portability}&quot;">​</a></h3><p>CI/CD平台差异包括Shell、路径分隔符和工具预装版本。Linux工作流不证明Windows或macOS通过；旧GitLab/Drone草稿的容器、注册表和部署命令只保留历史入口，不作为当前模板。</p><h3 id="part-3-legacy-notes-drone-webhook" tabindex="-1">从 Gogs/Drone 草稿区分事件、调度和构建故障 <a class="header-anchor" href="#part-3-legacy-notes-drone-webhook" aria-label="Permalink to &quot;从 Gogs/Drone 草稿区分事件、调度和构建故障 {#part-3-legacy-notes-drone-webhook}&quot;">​</a></h3><p>Gogs Drone 同步激活后 CI 卡住怎样分层查？旧草稿记录“Gogs 建仓→Drone 同步仓库→激活仓库→配置推送 Webhook→测试投递→观察 CI”的链路，但明确写着流水线卡住、需要继续测试。仓库可见不等于激活成功，投递成功不等于 runner 已取到任务，任务启动也不等于构建及部署通过。排错按这几层保留对应事件、提交标识、调度状态与步骤日志，避免反复修改业务代码解决未触发事件。</p><p>旧 Drone YAML 能直接部署吗？原 Go 1.11.4 镜像、私有镜像名、明文主机和密钥字段均属于历史环境；Webhook 密钥没有配置依据，不能复制“不需要改密钥”的建议。构建步骤与部署步骤应分开，秘密从受控配置注入并限制使用范围。旧示例把删除镜像、构建及交互式容器启动放在一段脚本，不能证明非交互 runner、构建上下文、端口和目标环境可用。</p><p>撤回旧 .drone.yml 作为可运行部署模板的地位；保留的是注册、触发、调度、执行逐层定位的方法。本节未连接 Gogs/Drone、未投递 Webhook、未构建镜像，也不声明与当前平台配置兼容。</p><h2 id="part-4" tabindex="-1">GitLab CI 与公司容器仓库草稿 <a class="header-anchor" href="#part-4" aria-label="Permalink to &quot;GitLab CI 与公司容器仓库草稿 {#part-4}&quot;">​</a></h2><blockquote><p>以下保留原资料的历史版本范围。</p></blockquote><blockquote><p>公司历史草稿：仅包含局部流水线和原仓库登录命令，缺少完整任务与变量设置，不能直接作为可运行的 CI 模板。</p></blockquote><h3 id="part-4-docker-自动build" tabindex="-1">docker 自动build <a class="header-anchor" href="#part-4-docker-自动build" aria-label="Permalink to &quot;docker 自动build {#part-4-docker-自动build}&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">docker:latest</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">variables</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    DOCKER_TLS_CERTDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/certs&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p><a href="https://www.jianshu.com/p/3c0cbb6c2936" target="_blank" rel="noopener noreferrer">https://www.jianshu.com/p/3c0cbb6c2936</a></p><p><a href="https://blog.csdn.net/qq_24046745/article/details/94405188" target="_blank" rel="noopener noreferrer">https://blog.csdn.net/qq_24046745/article/details/94405188</a></p><p>kubectl create secret docker-registry regcred <br> --docker-server=registry.example.invalid <br> --docker-username=REGISTRY_USER_PLACEHOLDER <br> --docker-password=REGISTRY_PASSWORD_PLACEHOLDER</p><p><span id="part-4-gitlab-ci"></span></p>`,41)])])}const u=a(s,[["render",o]]);export{k as __pageData,u as default};
